def lca_deepest_leaves(root):
    def dfs(node):
        """Return (depth of this subtree, LCA of its deepest nodes)."""
        if node is None:
            return 0, None
        ld, la = dfs(node.left)
        rd, ra = dfs(node.right)
        if ld == rd:
            return ld + 1, node          # deepest nodes on both sides
        return (ld + 1, la) if ld > rd else (rd + 1, ra)

    return dfs(root)[1]
